SELECT sub.d_year, sub.hd_buy_potential, SUM(sub.sr_net_loss) AS total_net_loss FROM (SELECT sr.sr_net_loss, d.d_year, hd.hd_buy_potential, t.t_hour FROM store_returns sr JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk JOIN time_dim t ON sr.sr_return_time_sk = t.t_time_sk JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk WHERE d.d_year = 1926 AND t.t_hour BETWEEN 20 AND 4) sub GROUP BY sub.d_year, sub.hd_buy_potential HAVING COUNT(*) > 2451966
